SELECT ?languageLabel WHERE {
  wd:Q1474863 wdt:P407 ?language .
  ?language wdt:P279 wd:Q50868 .
  ?language wdt:P282 wd:Q132659 .
  ?language wdt:P155 wd:Q447117 .
  ?language wdt:P156 wd:Q1852329, wd:Q123735278 .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en" . }
}

SELECT ?flagLabel WHERE {
  ?flag wdt:P279 wd:Q14660 ;
        wdt:P2579 wd:Q186083 ;
        wdt:P1343 wd:Q867541 ;
        wdt:P1368 "000319938" ;
        wdt:P910 wd:Q7851170 ;
        wdt:P1889 wd:Q102421356 .
  wd:Q351240 wdt:P279 ?flag .
  wd:Q2054905 wdt:P279 ?flag .
  wd:Q359236 wdt:P279 ?flag .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en" . }
