SELECT ?scientist ?scientistLabel WHERE {
  ?scientist wdt:P19 wd:Q20071 ;
             wdt:P69 wd:Q193510, wd:Q131262 .
  {
    SELECT ?scientist (COUNT(DISTINCT ?cat1) AS ?catCount) WHERE {
      { ?cat1 wdt:P301 ?scientist } UNION { ?cat1 wdt:P971 ?scientist }
    } GROUP BY ?scientist
    HAVING(?catCount >= 2)
  }
  wd:Q498967 wdt:P138 ?scientist .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?player ?playerLabel WHERE {
  ?player wdt:P19 wd:Q2018560 ;
          wdt:P20 wd:Q2018560 ;
          wdt:P54 wd:Q213417 ;
          wdt:P26 wd:Q6819834 .
  wd:Q1304614 wdt:P161 ?player .
  {
    SELECT ?player (COUNT(?statProp) AS ?count) WHERE {
      VALUES ?statProp { wdt:P9184 wdt:P9220 wdt:P9225 wdt:P9217 wdt:P9188 wdt:P9190 wdt:P9180 }
      ?player ?statProp ?value .
    } GROUP BY ?player
    HAVING(?count >= 6)
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?locationLabel WHERE {
  wd:Q122371 wdt:P276 ?location .
  {
    SELECT ?event WHERE {
      ?event wdt:P407 ?lang .
    } GROUP BY ?event HAVING(COUNT(DISTINCT ?lang) >= 4)
  }
  BIND(wd:Q122371 AS ?event)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
